///
///   1. drafting.drawio, cell <c>slice-draft-history</c>: <c>status="in-design"</c> → <c>status="ready"</c>
///   2. here: delete the three <c>Skip = …</c> arguments (codegen will then REPORT them as
///      TESTS STILL SKIPPED ON A CLAIMED SLICE until you do, but it will not edit them for you —
///      rewriting an attribute inside a hand-owned test file is how a generator destroys work)
///
/// Verified by doing exactly step 2 locally: all three pass, and each of the two load-bearing ones fails
/// when and only when the fold it guards is broken. See the mutation checks recorded in
/// <see cref="TheRowSCurrentSubjectIsTheLatestRevision"/>.
///
/// GIVEN/THEN, NOT GIVEN/WHEN/THEN. A read model only reads events that already exist, so there is no
/// command to be the WHEN and inventing one would be inventing a requirement. Understanding
/// EventSourcing ch. 3: "you typically do not use GWTs but GTs (Given - Then)."
/// </summary>
public sealed class DraftHistoryTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private const string OriginalSubject = "Original subject";
    private const string FirstRevision = "A better subject";
    private const string SecondRevision = "The best subject";

    private static readonly DateTimeOffset FirstRevisedAt = SeedData.SeededAt.AddHours(1);
    private static readonly DateTimeOffset SecondRevisedAt = SeedData.SeededAt.AddHours(2);

    private static EmailDrafted Drafted(string subject = OriginalSubject) => new(
        SeedData.EmailId, "someone@example.com", subject, "Body", SeedData.SeededAt);

    /// <summary>THEN: the rows this view holds, so a test can assert HOW MANY as well as which.</summary>
    private async Task<IReadOnlyList<DraftHistory>> Rows()
    {
        await using var session = Store.QuerySession();
        return await session.Query<DraftHistory>().ToListAsync();
    }

    // a new draft has an empty revision list
    //   GIVEN EmailDrafted
    //   THEN  DraftHistory
    //   (no WHEN: this is a GIVEN/THEN. Append the GIVEN, then assert the read model through its endpoint.)
    //
    // THIS IS THE TEST THAT RULES OUT THE OTHER ROW SHAPE. One row per revision — an EventProjection,
    // which is what DeliveryLog is in state-view/ — would give a brand-new draft NO ROW AT ALL, and the
    // screen reading it would show nothing for a draft that certainly exists. Asserting "a row, with an
    // empty group" is the difference between the two shapes stated as an assertion.
    //
    // EMPTY, NOT NULL, and that is a second claim: `Revision[] Revisions { get; init; } = []`. A nullable
    // group pushes a null check into every consumer for a state — "drafted, never revised" — that is
    // completely ordinary.
    [Fact]
    public async Task ANewDraftHasAnEmptyRevisionList()
    {
        await Given(SeedData.EmailId, Drafted());

        var row = (await Rows()).ShouldHaveSingleItem();

        row.Id.ShouldBe(SeedData.EmailId);
        row.EmailId.ShouldBe(SeedData.EmailId);
        row.Subject.ShouldBe(OriginalSubject);

        row.Revisions.ShouldNotBeNull();
        row.Revisions.ShouldBeEmpty();
    }

    // each revision is appended to the row's own list
    //   GIVEN EmailDrafted, SubjectRevised, SubjectRevised
    //   THEN  DraftHistory
    //   (no WHEN: this is a GIVEN/THEN. Append the GIVEN, then assert the read model through its endpoint.)
    //
    // TWO revisions, still ONE row, with two members INSIDE it — the whole point of the shape. A
    // projection keyed on the revision rather than on the draft satisfies nothing here, and neither does
    // a fold that overwrites the group instead of appending to it.
    [Fact]
    public async Task EachRevisionIsAppendedToTheRowSOwnList()
    {
        await Given(SeedData.EmailId,
            Drafted(),
            new SubjectRevised(SeedData.EmailId, FirstRevision, FirstRevisedAt),
            new SubjectRevised(SeedData.EmailId, SecondRevision, SecondRevisedAt));

        // ONE row. Asserted as a count over the whole view, not as a load by id, because a load by id
        // would pass just as well with a second row sitting next to it.
        var row = (await Rows()).ShouldHaveSingleItem();

        // TWO members, IN ORDER. Order is a claim: it is the stream's order, which is what makes
        // Revisions[^1] the latest revision and lets a screen render a history without sorting.
        row.Revisions.Length.ShouldBe(2);
        row.Revisions[0].ShouldBe(new Revision(FirstRevision, FirstRevisedAt));
        row.Revisions[1].ShouldBe(new Revision(SecondRevision, SecondRevisedAt));

        // The ORIGINAL subject is not a revision. Nobody revised it to that; it is where the draft
        // started. So the group holds 2 and not 3, and the row's own Subject is where "now" lives.
        row.Revisions.ShouldNotContain(r => r.RevisedTo == OriginalSubject);
    }

    // the row's current subject is the latest revision
    //   GIVEN EmailDrafted, SubjectRevised
    //   THEN  DraftHistory
    //   (no WHEN: this is a GIVEN/THEN. Append the GIVEN, then assert the read model through its endpoint.)
    //
    // THE HEAD AND THE GROUP MUST AGREE. A row carrying a header AND its repeated lines can be
    // internally inconsistent, which a row with only one of the two cannot, and this is the only test
    // that looks at both at once.
    //
    // MUTATION-CHECKED, because a test that claims to catch something nothing else would has to be made
    // to fail on purpose at least once. Dropping `Subject = e.Subject` from
    // DraftHistoryProjection.Apply(SubjectRevised, …) — so the fold appends a revision and leaves the
    // header behind — fails THIS TEST AND NOTHING ELSE in the suite: Failed: 1, Passed: 15, Total: 16.
    // Both other GIVEN/THENs here stay green, because one never revises and the other only reads the
    // group and its count.
    [Fact]
    public async Task TheRowSCurrentSubjectIsTheLatestRevision()
    {
        await Given(SeedData.EmailId,
            Drafted(),
            new SubjectRevised(SeedData.EmailId, FirstRevision, FirstRevisedAt));

        var row = (await Rows()).ShouldHaveSingleItem();

        var revision = row.Revisions.ShouldHaveSingleItem();

        // The head moved...
        row.Subject.ShouldBe(FirstRevision);
        row.Subject.ShouldNotBe(OriginalSubject);
        // ...and it moved to exactly what the history says was applied last.
        row.Subject.ShouldBe(revision.RevisedTo);

        // mappings="revisedTo=subject", discharged: the child's RevisedTo IS the event's subject, under
        // another name. This is the only place in the kit where a rename has to resolve THROUGH a
        // repeated group, so it is the only place the claim is exercised.
        revision.RevisedTo.ShouldBe(FirstRevision);
        revision.RevisedAt.ShouldBe(FirstRevisedAt);
    }
}
